<?php

declare(strict_types=1);

namespace Patchlevel\Hydrator\Extension\Generated;

use Patchlevel\Hydrator\Mapper\CallStack;
use Patchlevel\Hydrator\Mapper\Mapper;
use Patchlevel\Hydrator\Mapper\MapperFactory;
use Patchlevel\Hydrator\Metadata\ClassMetadata;
use Patchlevel\Hydrator\StackHydrator;
use WeakMap;

use function assert;
use function class_exists;
use function is_file;

/**
 * Loads the generated mapper of a class. If there is none, because the class was not warmed up or changed since, null
 * is returned and the class is mapped with reflection. The code is only generated by the {@see GeneratedMapperWarmer}.
 *
 * @internal registered by the {@see GeneratedMapperExtension}
 */
final class GeneratedMapperFactory implements MapperFactory
{
    /** @var WeakMap<StackHydrator, CallStack> the generated mappers of a hydrator share their call stack */
    private WeakMap $callStacks;

    public function __construct(
        private readonly MapperFiles $files,
    ) {
        $this->callStacks = new WeakMap();
    }

    /**
     * @param ClassMetadata<T> $metadata
     *
     * @return Mapper<T>|null
     *
     * @template T of object
     */
    public function create(ClassMetadata $metadata, StackHydrator $hydrator): Mapper|null
    {
        $className = $this->files->className($metadata);
        $fqcn = $this->files->fqcn($className);

        if (!class_exists($fqcn, false)) {
            $file = $this->files->path($className);

            if (!is_file($file)) {
                return null;
            }

            require_once $file;
        }

        /** @var Mapper<T> $mapper */
        $mapper = new $fqcn($metadata, $hydrator, $this->callStacks[$hydrator] ??= new CallStack());
        assert($mapper instanceof GeneratedMapper);

        $filter = $hydrator->propertyFilter();

        if ($filter === null) {
            return $mapper;
        }

        return new FilteredMapper($mapper, $filter);
    }
}
